    """Convert a hex character to its integer value."""
    if digit.isdigit():
        return int(digit)
    elif 'a' <= digit.lower() <= 'f':
        return ord(digit.lower()) - ord('a') + 10
    return None

def count_prime_hex_digits(hex_string):
    """Count the number of prime hex digits in a string."""
    return sum(
        1 for char in hex_string
        if (value := hex_digit_value(char)) is not None and is_prime(value)
    )

