def is_monotonic(nums):
    """
    Checks if a list is monotonic (non-decreasing or non-increasing).

    Args:
        nums: A list of numbers.

    Returns:
        True if the list is monotonic, False otherwise.
    """
    if not nums:
        return True

    # Determine the direction using first non-equal pair
    try:
        direction = next((1 if nums[i] < nums[i+1] else -1 
                         for i in range(len(nums)-1) 
                         if nums[i] != nums[i+1]), 0)
    except StopIteration:
        return True

    # If all elements are equal, it's monotonic
    if direction == 0:
        return True

    # Check if all subsequent pairs follow the same direction
    return all(
        (direction > 0 and nums[i] <= nums[i+1]) or 
        (direction < 0 and nums[i] >= nums[i+1])
        for i in range(len(nums)-1)
    )
