    Encodes a string using a Caesar cipher with a shift of 5.
    Only shifts alphabetic characters; other characters remain unchanged.
    """
    return "".join(
        [
            chr((ord(char) - ord('a') + 5) % 26 + ord('a'))
            if 'a' <= char <= 'z'
            else (
                chr((ord(char) - ord('A') + 5) % 26 + ord('A'))
                if 'A' <= char <= 'Z'
